// ============================================
// VALIDATION INPUT - LLM Request Validator (RFC-014)
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Context fields for tracing (OPTIONAL - RFC-014) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required field: user_request ---
if (!userRequest || typeof userRequest !== 'string' || userRequest.trim().length === 0) {
  errors.push('user_request requis (chaine non vide)');
}

// --- Required field: domain ---
const domain = body.domain || ctx.domain;
if (!domain || typeof domain !== 'object') {
  errors.push('domain requis (objet)');
} else {
  if (!domain.name) errors.push('domain.name requis');
  if (!domain.description) errors.push('domain.description requis');
}

// --- API Key from request or env ---
const anthropicApiKey = body.anthropic_api_key || body.plugin_context?.api_keys?.anthropic || $env.ANTHROPIC_API_KEY || '';
if (!anthropicApiKey) {
  errors.push('anthropic_api_key requis (via request ou env)');
}

// --- Optional fields ---
const hasImage = body.has_image === true;
const imageAttachments = Array.isArray(body.image_attachments) ? body.image_attachments : [];
const model = body.model || ctx.model || 'claude-haiku-4-5-20251001';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  user_request: userRequest.trim(),
  domain: domain,
  user_id: userId,
  guild_id: guildId,
  anthropic_api_key: anthropicApiKey,
  model: model,
  has_image: hasImage,
  image_attachments: imageAttachments,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

const data = $input.first().json;

// === HELPERS ===
const formatValue = (v) => Array.isArray(v) ? v.join(' | ') : v;
const MAX_HINTS = data.domain.max_hints_per_level || 5;

// === SECTION CONTRADICTIONS (dynamique) ===
const contradictionSection = data.domain.contradiction_examples?.length > 0
  ? `Exemples de contradictions pour ${data.domain.name} :\n${data.domain.contradiction_examples.map(e => `- ${e}`).join('\n')}`
  : `Identifie les contradictions logiques dans le contexte "${data.domain.name}"`;

// === SECTION OUT OF SCOPE (dynamique) ===
const outOfScopeSection = data.domain.out_of_scope_examples?.length > 0
  ? `\n\nExemples de requetes HORS SCOPE (a rejeter) :\n${data.domain.out_of_scope_examples.map(e => `- "${e}"`).join('\n')}`
  : '';

// === SECTION CONTRAINTES (dynamique) ===
let constraintsSection;
let constraintsKeys;
if (data.domain.constraints_schema && Object.keys(data.domain.constraints_schema).length > 0) {
  constraintsKeys = Object.keys(data.domain.constraints_schema);
  constraintsSection = `Contraintes a extraire (UTILISE UNIQUEMENT ces valeurs) :\n` +
    Object.entries(data.domain.constraints_schema)
      .map(([key, values]) => `- ${key} : ${formatValue(values)}`)
      .join('\n');
} else {
  constraintsKeys = ['time', 'budget'];
  constraintsSection = `Contraintes a extraire :\n- time : very_short | short | medium | long | null\n- budget : low | medium | high | null\n- Extrais toute autre contrainte pertinente mentionnee`;
}

// === SECTION NIVEAU UTILISATEUR (dynamique) ===
let userLevelSection;
if (data.domain.user_level_hints && Object.keys(data.domain.user_level_hints).length > 0) {
  userLevelSection = Object.entries(data.domain.user_level_hints)
    .map(([level, hints]) => `- ${level} : ${hints.slice(0, MAX_HINTS).map(h => `"${h}"`).join(', ')}`)
    .join('\n');
} else {
  userLevelSection = `- beginner : indices de debutant, demandes d'aide basique\n- intermediate : requetes standard sans difficulte particuliere\n- advanced : termes techniques, demandes complexes\n- unknown : impossible a determiner`;
}

// === SCHEMA JSON DYNAMIQUE ===
const constraintsJsonSchema = constraintsKeys.map(k => `      "${k}": "valeur ou null"`).join(',\n');

// === SECTION ATTACHMENTS ===
let attachmentContext = '';
if (data.has_image && data.image_attachments && data.image_attachments.length > 0) {
  const attachmentList = data.image_attachments.map(a => {
    const filename = a.filename || 'fichier';
    const contentType = a.content_type || 'unknown';
    return `- ${filename} (${contentType})`;
  }).join('\n');
  attachmentContext = `\n\n[FICHIERS ATTACHES]\nL'utilisateur a joint ${data.image_attachments.length} fichier(s) a sa requete :\n${attachmentList}\n\nPRENDS EN COMPTE ces fichiers joints lors de la validation. Une requete demandant de "scanner", "analyser", "lire" ou "extraire" un document est VALIDE si un fichier est attache.`;
}

// === PROMPT SYSTEM ===
const systemPrompt = `Tu es un validateur de requetes pour ${data.domain.bot_name || data.domain.name}.

DOMAINE : ${data.domain.name}
${data.domain.description}${outOfScopeSection}

---

# PARTIE 1 : VALIDATION

## ETAPE 1 - PERTINENCE
La requete concerne-t-elle ce domaine ?
- Juge si la requete a un lien direct avec ${data.domain.name}
- Ne liste PAS ce qui est hors scope, deduis-le du domaine defini
- Si l'utilisateur a joint des fichiers, considere que la requete peut concerner ces fichiers

## ETAPE 2 - COHERENCE (uniquement si pertinent au domaine)
Les contraintes de la requete sont-elles compatibles entre elles ?

${contradictionSection}

---

# PARTIE 2 : ANALYSE DE L'ETAT UTILISATEUR

Analyse le message pour comprendre l'etat emotionnel et contextuel de l'utilisateur.

## Emotions a detecter
- stress : pression, anxiete ("je dois", "il faut que", "j'ai pas le temps")
- fatigue : epuisement ("creve", "fatigue", "pas envie", "flemme")
- frustration : agacement ("j'en ai marre", "rien ne marche", "encore")
- motivation : enthousiasme ("j'ai envie de", "je veux essayer", "ca me tente")
- curiosity : decouverte ("c'est quoi", "comment on fait", "je me demande")
- joy : plaisir ("j'adore", "genial", "super")
- neutral : pas d'emotion particuliere detectee

## Urgence
- high : contrainte temps explicite courte (<30min) ou mots d'urgence ("vite", "urgent", "tout de suite")
- medium : contrainte temps moderee ou implicite
- low : pas de pression temporelle

## ${constraintsSection}

## Niveau utilisateur
${userLevelSection}

## Ton recommande
- reassuring : si stress, fatigue ou frustration -> rassurer, simplifier
- direct : si urgence high -> aller droit au but
- enthusiastic : si motivation ou joy -> partager l'enthousiasme
- pedagogical : si curiosity ou beginner -> expliquer
- neutral : si aucune emotion forte

---

# REPONSE

Reponds UNIQUEMENT en JSON valide, sans texte autour :

{
  "is_valid": true ou false,
  "issue_type": null ou "out_of_scope" ou "contradiction",
  "response": "message oriente solution si invalide, sinon null",
  "user_state": {
    "emotions": ["liste", "des", "emotions"],
    "urgency": "low" ou "medium" ou "high",
    "constraints": {
${constraintsJsonSchema}
    },
    "user_level": "beginner" ou "intermediate" ou "advanced" ou "unknown",
    "tone_preference": "reassuring" ou "direct" ou "enthusiastic" ou "pedagogical" ou "neutral"
  }
}

IMPORTANT pour la reponse si invalide :
- Sois poli et bienveillant
- Explique brievement le probleme
- Propose des alternatives concretes
- Pose une question pour guider l'utilisateur`;

// Build user message with attachment context
let userMessage = `Requete a valider : "${data.user_request}"`;
if (attachmentContext) {
  userMessage += attachmentContext;
}

const body = {
  model: data.model,
  max_tokens: 800,
  temperature: 0,
  messages: [
    { role: 'user', content: userMessage }
  ],
  system: systemPrompt
};

return [{
  json: {
    ...data,
    llm_body: JSON.stringify(body)
  }
}];

// ============================================
// PARSE LLM RESPONSE - LLM Request Validator
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Build dynamic default constraints from domain schema
const constraintsSchema = prevData.domain?.constraints_schema || {};
const defaultConstraints = {};
const schemaKeys = Object.keys(constraintsSchema);
if (schemaKeys.length > 0) {
  for (const key of schemaKeys) {
    defaultConstraints[key] = null;
  }
} else {
  defaultConstraints.time = null;
  defaultConstraints.budget = null;
}

// Default user_state for fail-open scenarios
const defaultUserState = {
  emotions: ["neutral"],
  urgency: "low",
  constraints: defaultConstraints,
  user_level: "unknown",
  tone_preference: "neutral"
};

// Helper to build trace
const buildTrace = (llmResponse, serviceResponse, errorStep = null) => ({
  llm_response: llmResponse,
  service_response: serviceResponse,
  provider: 'anthropic',
  model: prevData.model,
  tokens: { 
    input: input.usage?.input_tokens || null, 
    output: input.usage?.output_tokens || null 
  },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  error_step: errorStep
});

try {
  // Handle API error - fail-open with default state
  if (input.error) {
    return [{
      json: {
        success: true,
        is_valid: true,
        issue_type: null,
        response: null,
        user_state: defaultUserState,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _error: input.error.message,
        _trace: buildTrace(null, input, 'api_call')
      }
    }];
  }

  // Extract text content from Claude response
  let textContent = '';
  for (const block of (input.content || [])) {
    if (block.type === 'text') {
      textContent += block.text;
    }
  }

  // Parse JSON from response
  let result;
  try {
    const cleaned = textContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    result = JSON.parse(cleaned);
  } catch (e) {
    // If parsing fails, assume valid request with default state (fail-open)
    return [{
      json: {
        success: true,
        is_valid: true,
        issue_type: null,
        response: null,
        user_state: defaultUserState,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _parse_error: e.message,
        _trace: buildTrace(textContent, input, 'json_parse')
      }
    }];
  }

  // Validate and normalize user_state
  const userState = result.user_state || {};

  // Build normalized constraints from schema keys
  const normalizedConstraints = {};
  const keysToUse = schemaKeys.length > 0 ? schemaKeys : ['time', 'budget'];
  for (const key of keysToUse) {
    normalizedConstraints[key] = userState.constraints?.[key] || null;
  }

  const normalizedUserState = {
    emotions: Array.isArray(userState.emotions) ? userState.emotions : ["neutral"],
    urgency: ["low", "medium", "high"].includes(userState.urgency) ? userState.urgency : "low",
    constraints: normalizedConstraints,
    user_level: ["beginner", "intermediate", "advanced", "unknown"].includes(userState.user_level) 
      ? userState.user_level : "unknown",
    tone_preference: ["reassuring", "direct", "enthusiastic", "pedagogical", "neutral"].includes(userState.tone_preference)
      ? userState.tone_preference : "neutral"
  };

  // Return RFC-044 compliant format with trace
  return [{
    json: {
      success: true,
      is_valid: result.is_valid ?? true,
      issue_type: result.issue_type || null,
      response: result.response || null,
      user_state: normalizedUserState,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: buildTrace(textContent, input)
    }
  }];
} catch (e) {
  // Fail-open: accept request with default state if error
  return [{
    json: {
      success: true,
      is_valid: true,
      issue_type: null,
      response: null,
      user_state: defaultUserState,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _error: e.message,
      _trace: buildTrace(null, input, 'unexpected_error')
    }
  }];
}

